INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (11, 22, 'theory', 'Quiz: Inside the Browser');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 22, 0, 'In what order will these run: setTimeout(A, 0); Promise.resolve().then(B); synchronous C?', '["A, B, C", "C, A, B", "C, B, A", "B, C, A"]', 2, 'First the synchronous code (C), then the microtask queue (B), and only then the next task, the timer (A).');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 22, 1, 'Which properties are cheapest to animate?', '["width and height", "transform and opacity: compositing is often enough", "margin and padding", "font-size"]', 1, 'width and margin cause layout and paint, while transform and opacity are handled at the compositing step on the GPU.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 22, 2, 'What happens if a single task runs for 300 ms?', '["The page will not react to clicks and will skip frames until the task finishes", "Nothing: the browser is multithreaded", "The task will be interrupted", "The timer will fire earlier"]', 0, 'Tasks are not interrupted; there is only one main thread, so long tasks are split into pieces (up to 50 ms) and control is handed back to the event loop.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 22, 3, 'How do defer and async differ on a <script>?', '["async is always faster", "defer blocks HTML parsing", "defer runs after parsing, in order, while async runs as soon as it has downloaded", "There is no difference between them"]', 2, 'A regular script stops parsing, while defer and async do not; modules (type=module) behave like defer.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 22, 4, 'What are Web Workers for?', '["To access the DOM from another thread", "To run heavy computations in a separate thread with its own event loop without blocking the interface", "To speed up the network", "To store cookies"]', 1, 'A worker has no access to the DOM; it talks to the main thread with messages through postMessage, and the data is copied by structured clone.');
